#include <bits/stdc++.h>
using namespace std;

struct IntStack {
    vector<int> array;
    int size = 0;

    IntStack() {
        array.reserve(8);
    }

    void push(int item) {
        if (size >= (int)array.size()) {
            array.resize(array.size() * 2 + 1);
        }
        if (size < (int)array.size()) {
            array[size] = item;
        } else {
            array.push_back(item);
        }
        size++;
    }

    int get(int i) {
        assert(i >= 0 && i < size);
        return array[i];
    }

    int getSize() {
        return size;
    }
};

template<typename M>
struct NumberTheory {
    struct Modulus {
        virtual long long modulus() const = 0;

        vector<long long> factorial;
        vector<long long> invFactorial;

        Modulus() {
            factorial.push_back(1);
            invFactorial.push_back(1);
        }

        long long fact(int n) {
            while ((int)factorial.size() <= n) {
                factorial.push_back(mult(factorial.back(), (long long)factorial.size()));
            }
            return factorial[n];
        }

        long long fInv(int n) {
            int lastKnown = (int)invFactorial.size() - 1;
            if (lastKnown < n) {
                vector<long long> fInv(n - lastKnown);
                fInv[0] = mult(fact(n), inv(fact(n)));
                for (int i = 1; i < (int)fInv.size(); i++) {
                    fInv[i] = mult(fInv[i - 1], n - i + 1);
                }
                for (int i = (int)fInv.size() - 1; i >= 0; i--) {
                    if ((int)invFactorial.size() <= n - i) {
                        invFactorial.resize(n - i + 1);
                    }
                    invFactorial[n - i] = fInv[i];
                }
            }
            return invFactorial[n];
        }

        long long paritySign(long long k) {
            return (k & 1) ? modulus() - 1 : 1;
        }

        long long ncr(int n, int r) {
            if (n < 0 || r < 0 || n < r) return 0;
            return mult(fact(n), mult(fInv(r), fInv(n - r)));
        }

        long long smallInv(int n) {
            return mult(fInv(n), fact(n - 1));
        }

        long long add(long long a, long long b) {
            long long v = a + b;
            return v < modulus() ? v : v - modulus();
        }

        long long mult(long long a, long long b) {
            return (a * b) % modulus();
        }

        long long inv(long long a) {
            return pow(a, modulus() - 2);
        }

        long long pow(long long base, long long exp) {
            long long result = 1;
            long long cur = base % modulus();
            while (exp > 0) {
                if (exp & 1) result = mult(result, cur);
                cur = mult(cur, cur);
                exp >>= 1;
            }
            return result;
        }
    };

    struct Mod998 : public Modulus {
        long long modulus() const override {
            return 998244353LL;
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    NumberTheory<NumberTheory<>::Mod998> nt;
    auto &mod = nt;

    long long modVal = mod.modulus();

    // Since the original code calls mod.fInv(n + m), we do the same
    mod.fInv(n + m);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        p = mod.mult(p, n - i, mod.smallInv(n + m - i));
        phaseSize = mod.add(phaseSize, p);
        if (i >= n) break; // To prevent infinite loop if p becomes 0
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long term = mod.paritySign(k + 1);
        term = mod.mult(term, mod.ncr(n, k));
        term = mod.mult(term, m + k);
        term = mod.mult(term, mod.smallInv(k));
        term = mod.mult(term, phaseSize);
        answer = mod.add(answer, term);
    }

    cout << answer << "\n";

    return 0;
}

